import{_ as e,o as a,c as o,ah as r}from"./chunks/framework.D4KxWb5R.js";const p=JSON.parse('{"title":"Technical integration: overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/integration/overview.md","filePath":"src/en/guide/integration/overview.md"}'),i={name:"en/guide/integration/overview.md"};function d(n,t,h,s,c,l){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="technical-integration-overview" tabindex="-1">Technical integration: overview <a class="header-anchor" href="#technical-integration-overview" aria-label="Permalink to &quot;Technical integration: overview&quot;">​</a></h1><p>This part is for the technical teams of the products that connect their back-office to M&#39;City IQ. It describes the full contract; Auticway is its first implementation.</p><h2 id="the-four-links" tabindex="-1">The four links <a class="header-anchor" href="#the-four-links" aria-label="Permalink to &quot;The four links&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Link</th><th>Direction</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="./sso.html">SSO (OpenID Connect)</a></td><td>Product → M&#39;City</td><td>M&#39;City staff sign in to the back-office with their M&#39;City account.</td></tr><tr><td><a href="./api.html">API</a></td><td>Product → M&#39;City</td><td>The product reads its record and updates its access URL and languages.</td></tr><tr><td><a href="./webhook.html">Webhook</a></td><td>M&#39;City → product</td><td>M&#39;City pushes the product record on every change.</td></tr><tr><td><a href="./indicators.html">Indicators</a></td><td>Product → M&#39;City</td><td>The product reports its consolidated indicators, pushed or polled.</td></tr></tbody></table><p>M&#39;City IQ only receives aggregated values, never personal data of the product&#39;s users.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to &quot;Environments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>OIDC issuer</th><th>API base</th></tr></thead><tbody><tr><td>Production</td><td><code>https://mcityiq.com</code></td><td><code>https://mcityiq.com/api/v1</code></td></tr><tr><td>Test</td><td><code>https://mcity.edpage.net</code></td><td><code>https://mcity.edpage.net/api/v1</code></td></tr></tbody></table><p>Credentials from one don&#39;t work on the other.</p><h2 id="what-the-ceo-hands-you" tabindex="-1">What the CEO hands you <a class="header-anchor" href="#what-the-ceo-hands-you" aria-label="Permalink to &quot;What the CEO hands you&quot;">​</a></h2><p>M&#39;City&#39;s CEO sets the product up in the registry (see <a href="./../administration/registry.html#integrating-a-product">Integrating a product</a>):</p><table tabindex="0"><thead><tr><th>Item</th><th>Where it is created</th><th>What you provide</th></tr></thead><tbody><tr><td>OIDC client ID and secret</td><td>SSO integration</td><td>The redirect URIs (HTTPS, 5 at most) and, if needed, the back-channel logout URI</td></tr><tr><td><code>mcity_…</code> service token</td><td>API integration</td><td>—</td></tr><tr><td>Webhook secret</td><td>API integration</td><td>The webhook URL and the back-office URL (for polling)</td></tr><tr><td>Product ID (UUID)</td><td>Product page</td><td>—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Secrets</p><p>Each secret is shown only once, then stored hashed or encrypted. It must reach you through a safe channel (a shared password manager, for example), never by plain e-mail or in a ticket. Regenerating one revokes the old one: plan to update your configuration at the same moment.</p></div><h2 id="shared-conventions" tabindex="-1">Shared conventions <a class="header-anchor" href="#shared-conventions" aria-label="Permalink to &quot;Shared conventions&quot;">​</a></h2><ul><li>JSON, <code>camelCase</code> fields, UUID identifiers, ISO 8601 dates in UTC.</li><li>Calls from M&#39;City to the product are signed with HMAC (see <a href="./webhook.html#verifying-the-signature">Webhook</a>); calls from the product to M&#39;City carry the service token.</li><li>M&#39;City doesn&#39;t follow redirects: declare the final URLs.</li></ul>',14)])])}const m=e(i,[["render",d]]);export{p as __pageData,m as default};
